<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\OperatingUnitService;

Auth::requirePermission('tables.manage');$tenantId=em_require_tenant();
try{$unit=(new OperatingUnitService())->requireCurrent();}catch(Throwable$e){em_header('Mesas e comandas','restaurant');?><div class="alert error"><?= Security::e($e->getMessage()) ?></div><?php em_footer();return;}$unitId=(int)$unit['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='table-save'){
        $id=(int)($_POST['id']??0);$name=mb_substr(trim((string)($_POST['name']??'')),0,120);$seats=max(1,min(100,(int)($_POST['seats']??4)));$status=(string)($_POST['status']??'available');if($name===''||!in_array($status,['available','occupied','inactive'],true)){em_flash('error','Mesa inválida.');em_go('restaurant');}
        try{Database::transaction(function(PDO$tx)use(&$id,$tenantId,$unitId,$name,$seats,$status):void{if($id>0){$q=$tx->prepare(Database::portableSql($tx,'SELECT id,status FROM restaurant_tables WHERE id=? AND tenant_id=? AND unit_id=? FOR UPDATE'));$q->execute([$id,$tenantId,$unitId]);$current=$q->fetch();if(!$current)throw new RuntimeException('Mesa não encontrada nesta unidade.');if($status==='inactive'){$open=$tx->prepare('SELECT COUNT(*) FROM tabs WHERE tenant_id=? AND table_id=? AND status="open"');$open->execute([$tenantId,$id]);if((int)$open->fetchColumn()>0)throw new RuntimeException('Encerre a comanda antes de inativar a mesa.');}$tx->prepare('UPDATE restaurant_tables SET name=?,seats=?,status=? WHERE id=? AND tenant_id=? AND unit_id=?')->execute([$name,$seats,$status,$id,$tenantId,$unitId]);}else{$s=$tx->prepare('INSERT INTO restaurant_tables (tenant_id,unit_id,name,seats,status,qr_token) VALUES (?,?,?,?,"available",?)');$s->execute([$tenantId,$unitId,$name,$seats,bin2hex(random_bytes(20))]);$id=(int)$tx->lastInsertId();}});Auth::audit('table.saved','table',(string)$id,['unit_id'=>$unitId]);em_flash('ok','Mesa salva em '.$unit['name'].'.');}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('restaurant');
    }
    if($action==='tab-open'){
        $tableId=(int)($_POST['table_id']??0);$label=mb_substr(trim((string)($_POST['label']??'')),0,160);
        try{$id=Database::transaction(function(PDO$tx)use($tableId,$tenantId,$unitId,$label):int{$t=$tx->prepare(Database::portableSql($tx,'SELECT id,status FROM restaurant_tables WHERE id=? AND tenant_id=? AND unit_id=? FOR UPDATE'));$t->execute([$tableId,$tenantId,$unitId]);$table=$t->fetch();if(!$table||$table['status']==='inactive')throw new RuntimeException('Mesa indisponível nesta unidade.');$open=$tx->prepare('SELECT id FROM tabs WHERE tenant_id=? AND table_id=? AND status="open"');$open->execute([$tenantId,$tableId]);if($open->fetchColumn())throw new RuntimeException('A mesa já possui comanda aberta.');$s=$tx->prepare('INSERT INTO tabs (tenant_id,table_id,opened_by,label,status) VALUES (?,?,?, ?,"open")');$s->execute([$tenantId,$tableId,Auth::id(),$label?:null]);$id=(int)$tx->lastInsertId();$tx->prepare('UPDATE restaurant_tables SET status="occupied" WHERE id=? AND tenant_id=? AND unit_id=?')->execute([$tableId,$tenantId,$unitId]);return$id;});Auth::audit('tab.opened','tab',(string)$id,['unit_id'=>$unitId]);em_flash('ok','Comanda aberta.');}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('restaurant');
    }
    if($action==='tab-close'){
        $id=(int)($_POST['id']??0);
        try{$tab=Database::transaction(function(PDO$tx)use($id,$tenantId,$unitId):array{$s=$tx->prepare(Database::portableSql($tx,'SELECT t.* FROM tabs t JOIN restaurant_tables rt ON rt.id=t.table_id AND rt.tenant_id=t.tenant_id WHERE t.id=? AND t.tenant_id=? AND rt.unit_id=? AND t.status="open" FOR UPDATE'));$s->execute([$id,$tenantId,$unitId]);$tab=$s->fetch();if(!$tab)throw new RuntimeException('Comanda não encontrada nesta unidade.');$u=$tx->prepare('SELECT COUNT(*) FROM orders WHERE tenant_id=? AND unit_id=? AND tab_id=? AND status<>"cancelled" AND payment_status<>"paid"');$u->execute([$tenantId,$unitId,$id]);if((int)$u->fetchColumn()>0)throw new RuntimeException('Existem pedidos não pagos nesta comanda.');$active=$tx->prepare('SELECT COUNT(*) FROM orders WHERE tenant_id=? AND unit_id=? AND tab_id=? AND status IN ("confirmed","preparing","ready","served")');$active->execute([$tenantId,$unitId,$id]);if((int)$active->fetchColumn()>0)throw new RuntimeException('Existem pedidos operacionais ainda ativos nesta comanda.');$tx->prepare('UPDATE tabs SET status="closed",closed_by=?,closed_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=?')->execute([Auth::id(),$id,$tenantId]);if($tab['table_id'])$tx->prepare('UPDATE restaurant_tables SET status="available" WHERE id=? AND tenant_id=? AND unit_id=?')->execute([$tab['table_id'],$tenantId,$unitId]);return$tab;});Auth::audit('tab.closed','tab',(string)$id,['unit_id'=>$unitId]);em_flash('ok','Comanda encerrada.');}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('restaurant');
    }
}
$s=$pdo->prepare('SELECT rt.*,tb.id open_tab_id,tb.label,(SELECT COALESCE(SUM(o.total_cents),0) FROM orders o WHERE o.tenant_id=rt.tenant_id AND o.unit_id=rt.unit_id AND o.tab_id=tb.id AND o.status<>"cancelled") tab_total,(SELECT COALESCE(SUM(GREATEST(0,o.total_cents-COALESCE((SELECT SUM(p.amount_cents) FROM payments p WHERE p.tenant_id=o.tenant_id AND p.order_id=o.id AND p.status="paid"),0))),0) FROM orders o WHERE o.tenant_id=rt.tenant_id AND o.unit_id=rt.unit_id AND o.tab_id=tb.id AND o.status<>"cancelled") unpaid_total FROM restaurant_tables rt LEFT JOIN tabs tb ON tb.table_id=rt.id AND tb.status="open" WHERE rt.tenant_id=? AND rt.unit_id=? ORDER BY rt.status="inactive",rt.name');$s->execute([$tenantId,$unitId]);$tables=$s->fetchAll();$occupied=count(array_filter($tables,static fn(array$t):bool=>(string)$t['status']==='occupied'));$openTabs=count(array_filter($tables,static fn(array$t):bool=>!empty($t['open_tab_id'])));
em_header('Mesas e comandas','restaurant');
?>
<section class="page-hero"><div><span class="eyebrow">SALÃO · <?= Security::e($unit['name']) ?></span><h2>Mesas e comandas</h2><p>O salão exibido pertence somente à unidade selecionada. Para administrar outra loja, troque a unidade no topo.</p></div><div class="hero-actions"><a class="button primary" href="#nova-mesa">+ Nova mesa</a><a class="button secondary" href="<?= Security::e(app_url('?route=pos')) ?>">Abrir PDV</a></div></section>
<section class="grid dashboard-metrics"><div class="card metric"><span class="muted">Mesas</span><strong><?= count($tables) ?></strong></div><div class="card metric"><span class="muted">Ocupadas</span><strong><?= $occupied ?></strong></div><div class="card metric"><span class="muted">Comandas abertas</span><strong><?= $openTabs ?></strong></div><div class="card metric"><span class="muted">Unidade</span><strong style="font-size:20px"><?= Security::e($unit['name']) ?></strong></div></section>
<div class="grid" style="grid-template-columns:minmax(280px,.75fr) minmax(0,2fr);margin-top:18px"><section class="card" id="nova-mesa"><span class="eyebrow">CADASTRO</span><h2>Nova mesa</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="table-save"><label>Nome<input name="name" placeholder="Mesa 01" required></label><label>Lugares<input type="number" name="seats" min="1" max="100" value="4"></label><div class="span-2 alert">Será criada em <strong><?= Security::e($unit['name']) ?></strong>.</div><button class="primary span-2">Criar mesa</button></form></section><section class="card"><div class="section-head"><div><span class="eyebrow">MAPA DO SALÃO</span><h2><?= Security::e($unit['name']) ?></h2></div><span class="muted"><?= count($tables) ?> mesas</span></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))"><?php foreach($tables as$t):?><article class="card"><div class="section-head"><h3><?= Security::e($t['name']) ?></h3><span class="status-pill <?= $t['status']==='available'?'active':($t['status']==='inactive'?'cancelled':'') ?>"><?= Security::e($t['status']) ?></span></div><p class="muted"><?= (int)$t['seats'] ?> lugares</p><?php if($t['open_tab_id']):?><p><strong>Comanda #<?= (int)$t['open_tab_id'] ?></strong><?= $t['label']?' · '.Security::e($t['label']):'' ?><br>Total: <strong><?= em_money($t['tab_total']) ?></strong><br><span class="muted">Ainda a receber: <?= em_money($t['unpaid_total']) ?></span></p><div class="actions"><a class="button secondary compact" href="<?= Security::e(app_url('?route=pos')) ?>">Lançar pedido</a><form method="post" onsubmit="return confirm('Encerrar esta comanda?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tab-close"><input type="hidden" name="id" value="<?= (int)$t['open_tab_id'] ?>"><button class="secondary compact">Encerrar</button></form></div><?php elseif($t['status']!=='inactive'):?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tab-open"><input type="hidden" name="table_id" value="<?= (int)$t['id'] ?>"><label>Identificação<input name="label" placeholder="João / aniversário"></label><button class="primary" style="margin-top:8px">Abrir comanda</button></form><?php endif;?><details style="margin-top:12px"><summary class="button secondary compact">Editar mesa</summary><form method="post" class="form-grid" style="margin-top:10px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="table-save"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><label>Nome<input name="name" required value="<?= Security::e($t['name']) ?>"></label><label>Lugares<input type="number" min="1" max="100" name="seats" value="<?= (int)$t['seats'] ?>"></label><label class="span-2">Status<select name="status"><option value="available"<?= em_selected($t['status'],'available') ?>>Disponível</option><option value="occupied"<?= em_selected($t['status'],'occupied') ?>>Ocupada</option><option value="inactive"<?= em_selected($t['status'],'inactive') ?>>Inativa</option></select></label><button class="secondary span-2">Salvar alterações</button></form></details><p style="margin-top:12px"><a href="<?= Security::e(app_url('mesa.php?t='.urlencode($t['qr_token']))) ?>" target="_blank" rel="noopener">Abrir link/QR da mesa</a></p></article><?php endforeach;?><?php if(!$tables):?><div class="alert">Nenhuma mesa cadastrada em <?= Security::e($unit['name']) ?>.</div><?php endif;?></div></section></div>
<?php em_footer();
